/* ---------------------------------------------------------------
   HELPERS
--------------------------------------------------------------- */
function attendancePct(attendance, studentId) {
  let present = 0, total = 0;
  Object.values(attendance).forEach(day => {
    if (day[studentId]) {
      total++;
      if (day[studentId] === "present") present++;
    }
  });
  return total ? Math.round((present / total) * 100) : 0;
}

function fmtINR(n) {
  return "₹" + Math.round(n).toLocaleString("en-IN");
}

function grade(pct) {
  if (pct >= 90) return { label: "A+", color: COLORS.sage };
  if (pct >= 75) return { label: "A", color: COLORS.sage };
  if (pct >= 60) return { label: "B", color: COLORS.amber };
  if (pct >= 40) return { label: "C", color: COLORS.crimson };
  return { label: "D", color: COLORS.crimsonDeep };
}

function initials(name) {
  return name.split(" ").map(p => p[0]).slice(0, 2).join("").toUpperCase();
}

